    orders.push({
      id: `ORD-${1001 + i}`,
      customer: CUSTOMERS[seed % CUSTOMERS.length],
      amount: 1200 + ((seed * 37) % 98000),
      createdAt: `2026-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`,
